from typing import List, Tuple

def process_input_and_find_min(N: int, beans: List[Tuple[int, int]]) -> int:
    color_min_deliciousness = {}

    for deliciousness, color in beans:
        if color not in color_min_deliciousness:
            color_min_deliciousness[color] = deliciousness
        else:
            color_min_deliciousness[color] = min(color_min_deliciousness[color], deliciousness)

    return max(color_min_deliciousness.values())
